use crate::{java_runtime::{Rc,RefCell},cn::wps::{moss::{app::{KmoBook::KmoBook,KmoBookApi::KmoBookApi},engine::linktb::LinkTable::ExternalBookBlock,filefmt::biff8::record::StandardRecord::StandardRecord,xlsxr::{util::UnifiedXmlReader::UnifiedXmlReader,xl::externalLinks::XlsxrExternalLinks::XlsxrExternalLinks}},et::ss::formula::constant::ErrorConstant::ErrorConstant}};
use super::ExternalLinkHandler::ExternalLinkHandler;
use serde_json::{json,Value};
use kfc_kfc_alpha::kfc::ooxfr::OxfrPackage::OxfrPackage;
use util::org::apache::poi::util::LittleEndianByteArrayOutput::LittleEndianByteArrayOutput;
use std::panic::{catch_unwind,AssertUnwindSafe};
fn thrown(e:Box<dyn std::any::Any+Send>)->String{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");for n in ["NullPointerException","ClassCastException","IllegalStateException","RuntimeException"]{if s.starts_with(n){return n.into();}}format!("panic: {s}")}
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>json!({"result":thrown(e)})}}
pub(crate) fn block(b:Option<&ExternalBookBlock>)->Value{let Some(b)=b else{return Value::Null;};let s=b.getExternalBookRecord().unwrap();let mut o=json!({"external":s.isExternalReferences(),"internal":s.isInternalReferences(),"url":call(||s.getURL()),"names":call(||s.getSheetNames()),"number":s.getNumberOfSheets()as i32,"definedCount":b.getNumberOfNames()});let mut bs=vec![];for c in b.getAllCRNBlock().borrow().iter(){let c=c.as_ref().unwrap();let mut rs=vec![];for r in c.getCrns(){let r=r.unwrap();let vs:Vec<_>=r.getConstantValues().unwrap().borrow().iter().map(|v|{let Some(v)=v else{return Value::Null;};let a=v.as_any();if let Some(d)=a.downcast_ref::<f64>(){json!({"kind":"number","bits":format!("{:016x}",d.to_bits())})}else if let Some(e)=a.downcast_ref::<ErrorConstant>(){json!({"kind":"error","code":e.getErrorCode()})}else if let Some(b)=a.downcast_ref::<bool>(){json!({"kind":"boolean","value":b})}else{json!({"kind":"string","value":a.downcast_ref::<String>().unwrap()})}}).collect();let mut out=LittleEndianByteArrayOutput::new();let mut record=call(||r.serialize(&mut out));record["bytes"]=json!(out.get_bytes().iter().map(|b|format!("{b:02x}")).collect::<String>());rs.push(json!({"first":r.getFirstColumn(),"last":r.getLastColumn(),"row":r.getRowIndex(),"values":vs,"record":record}));}bs.push(json!({"sheet":c.getSheetId(),"records":rs}));}o["blocks"]=json!(bs);o}
fn xml(p:&Value)->Value{let h=ExternalLinkHandler::ExternalLinkHandler(p["target"].as_str().map(str::to_string));let mut rows=vec![];for text in p["xml"].as_array().unwrap(){let mut r=call(||{UnifiedXmlReader::read(&mut std::io::Cursor::new(text.as_str().unwrap().as_bytes()),h.asElementHandler()).unwrap();Value::Null});r["block"]=block(h.getBookBlock().as_deref());rows.push(r);}json!({"history":rows})}
fn pipeline(book:&Rc<KmoBook>,mode:usize,root:&std::path::Path)->Value{let pack=kfc_kfc_alpha::kfc::opcr::ZipFile::ZipFile::from_path(root.join("zips").join(format!("java-{mode}.zip")).to_str().unwrap()).unwrap();let mut rels=kfc_kfc_alpha::kfc::opcr::OpcrRelationships::OpcrRelationships::OpcrRelationships(&pack,"xl/workbook.xml").unwrap();let ids=Rc::new(RefCell::new(vec![Some("rId2".into()),Some(if mode==2{"rId3"}else{"rId2"}.into()),Some("missing".into()),None,Some("rId2".into())]));let mut reader=XlsxrExternalLinks::XlsxrExternalLinks(book.clone(),Some(&mut rels),Some(ids.clone()));let mut history=vec![];for _ in 0..2{let mut row=call(||{reader.open().unwrap();Value::Null});let blocks=book.getLinkTable().borrow().getAllExternalBookBlocks().unwrap();let bs:Vec<_>=blocks.borrow().iter().map(|b|block(b.as_deref())).collect();row["blocks"]=json!(bs);row["duplicateAlias"]=json!(blocks.borrow().len()>2&&Rc::ptr_eq(blocks.borrow()[0].as_ref().unwrap(),blocks.borrow()[2].as_ref().unwrap()));history.push(row);ids.borrow_mut().push(Some("rId1".into()));}drop(reader);drop(pack);json!({"history":history})}
#[test]
fn original_android_external_links_sax_and_opc_reader(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/external-links-read-r0b44");let j:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let api=KmoBookApi::KmoBookApi();assert_eq!(api.open(root.join("rewrite-review/milestones/m1-xlsx-grid-read/fixtures/basic-types.xlsx").to_str().unwrap(),None,true),1);std::thread::sleep(std::time::Duration::from_millis(1000));let book=api.book();let actual=json!({"xml":input["cases"].as_array().unwrap().iter().map(xml).collect::<Vec<_>>(),"packages":[pipeline(&book,0,&p),pipeline(&book,2,&p)]});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&j,"root");}
#[test]
fn retained_inner_handler_keeps_original_outer_graph(){
    let h=ExternalLinkHandler::ExternalLinkHandler(Some("cached.xlsx".into()));let weak=Rc::downgrade(&h);let book=h.asElementHandler().enterSubElement(5195).unwrap();drop(h);assert!(weak.upgrade().is_some());let names=book.enterSubElement(5198).unwrap();drop(book);let name=names.enterSubElement(5201).unwrap();drop(names);assert!(weak.upgrade().is_some());name.characters("ignored by actual base");drop(name);assert!(weak.upgrade().is_none());
}
